import sys, math
def ip2i(s):
    a = list(map(int, s.split(".")))
    return (a[0] << 24) | (a[1] << 16) | (a[2] << 8) | a[3]
def i2ip(n):
    return ".".join(str((n >> s) & 255) for s in (24, 16, 8, 0))
